def section(content,kind=''): return f'<section class="section {kind}"><div class="wrap">{content}</div></section>'
def table(rows): return '<div class="table-wrap"><table><tbody>'+''.join(f'<tr><th scope="row">{a}</th><td>{b}</td></tr>' for a,b in rows)+'</tbody></table></div>'
def source(url,label='Manufacturer’s published information'): return f'<p class="note"><a href="{url}" target="_blank" rel="noopener">{label}</a>. Project-specific requirements and performance must be confirmed during engineering.</p>'

page('/solutions/','Aluminium Anodizing Solutions | Daimeng Technology','Compare vertical and horizontal anodizing lines, factory automation and supporting equipment. Find a solution for your aluminium finishing project.',header('SOLUTIONS','One production goal.<br>An integrated solution.','Explore the line configuration, equipment and control architecture that fit your factory.')+section(cards())+section('<div class="split"><div><span class="eyebrow">NOT SURE WHERE TO START?</span><h2>Let your production<br>guide the decision.</h2><p>Compare your product mix and factory constraints before deciding on a line configuration.</p>'+btn('Use the line selector','/line-selector/','dark')+'</div><div><h3>Beyond the main line</h3><p>Define the supporting equipment and interfaces early. Handling, process utilities and controls are all part of the production plan.</p><div class="actions">'+link('Explore supporting equipment','/anodizing-equipment/')+'</div></div></div>','muted')+cta())

vertical_faq=[('When should I consider a vertical anodizing line?','It is a starting point for projects focused on long aluminium profiles and continuous, high-volume production. Profile range, available building height and the process route must be reviewed together.'),('Can the line be connected to a factory management system?','Daimeng describes network interfaces for production information exchange with MES and ERP systems. The data fields, protocols and integration responsibilities should be agreed for each project.'),('What do I need for an initial proposal?','Prepare your profile drawings, expected monthly output, required finishes, factory dimensions, available utilities and target commissioning date.')]
vertical=header('VERTICAL ANODIZING','Built for long profiles.<br>Designed for flow.','Automatic vertical anodizing lines for aluminium extrusion projects, with coordinated handling and central process control.','vertical')
vertical+=section('<div class="split"><div><span class="eyebrow">THE PRODUCTION FIT</span><h2>Plan the line around<br>the profile.</h2><p>Vertical suspension and automated movement link the treatment stages. Start with the profile envelope and output mix, then confirm the factory layout and operating conditions.</p>'+link('Compare vertical and horizontal','/insights/vertical-vs-horizontal/')+'</div>'+table([('Workpieces','Aluminium profiles'),('Typical project focus','Long profiles and repeatable process routes'),('Handling concept','Vertical suspension and automated transfer'),('Process scope','Pretreatment, anodizing and specified finishing stages'),('Configuration','Engineered against your brief')])+'</div>')
vertical+=section('<span class="eyebrow">BEFORE YOU SPECIFY</span><h2>Three conversations worth having early.</h2><div class="process" style="grid-template-columns:repeat(3,1fr)"><div><strong>01</strong><h3>Building & access</h3><p>Review clear height, maintenance access, loading areas and the installation route.</p></div><div><strong>02</strong><h3>Finish & capacity</h3><p>Specify surface quality, finish mix and realistic production schedules.</p></div><div><strong>03</strong><h3>Connected control</h3><p>Define recipes, traceability and the information your factory needs.</p></div></div>','muted')
vertical+=section('<span class="eyebrow">COMMON QUESTIONS</span><h2>Planning a vertical line</h2>'+faq(vertical_faq))+cta()
page('/vertical-anodizing-line/','Automatic Vertical Anodizing Line | Daimeng Technology','Plan an automatic vertical aluminium anodizing line with Daimeng. Explore production fit, process planning, handling and factory control integration.',vertical,vertical_faq)

horizontal_faq=[('What profile lengths are listed for the horizontal line?','Daimeng publishes a profile length range of 100–15,000 mm. Actual equipment configuration depends on the profile mix, loading method and process requirements.'),('Is the published capacity a guaranteed output?','No. The published design range is 100–5,000 tonnes per month. A project-specific capacity assessment must account for alloy, surface area, film thickness, finish mix, loading and operating hours.'),('Can optional finishes be included?','The published process description includes optional polishing, coloring and electrophoretic coating. Confirm the exact route and equipment scope in the project specification.')]
horizontal=header('HORIZONTAL ANODIZING','Adapt the process.<br>Expand your possibilities.','A configurable horizontal line for aluminium profiles, different workpiece lengths and specified finishing routes.','horizontal')
horizontal+=section('<div class="section-heading"><div><span class="eyebrow">PUBLISHED DESIGN RANGE</span><h2>A starting point<br>for your specification.</h2></div><p>Use these ranges to begin a discussion, then validate the complete production scenario.</p></div>'+table([('Aluminium alloys','6061, 6063 and other alloys subject to process review'),('Profile length','100–15,000 mm'),('Profile cross-section','25 × 10 mm to 300 × 150 mm'),('Designed monthly capacity','100–5,000 tonnes / month'),('Anodic film thickness','5–50 μm, subject to customer requirements'),('Process options','Coloring, polishing and ED coating by configuration')])+source('https://en.daimengtech.com/products/卧式全自动阳极氧化生产线'))
horizontal+=section('<div class="split"><div><span class="eyebrow">DEFINE THE WHOLE ROUTE</span><h2>From the first load<br>to the final finish.</h2><p>A clear process specification helps align handling, tank layout, power, temperature control and downstream finishing before detailed engineering begins.</p>'+btn('Build your project brief','/contact/?solution=horizontal','dark')+'</div><div class="choice-panel"><h3>Your specification checklist</h3><ul><li>Profile envelope and weight distribution</li><li>Required finishes and quality criteria</li><li>Production mix and operating hours</li><li>Factory layout and utilities</li><li>Control and reporting requirements</li></ul></div></div>','muted')+section('<span class="eyebrow">COMMON QUESTIONS</span><h2>Planning a horizontal line</h2>'+faq(horizontal_faq))+cta()
page('/horizontal-anodizing-line/','Automatic Horizontal Anodizing Line | Daimeng Technology','Explore Daimeng horizontal anodizing lines for aluminium profiles. Review published profile ranges, finish options and project planning requirements.',horizontal,horizontal_faq)

auto_faq=[('How do fixed and flexible production modes differ?','Fixed mode follows a stable process and cycle. Flexible mode supports different finishing routes and film thickness requirements with coordinated equipment scheduling.'),('What should be agreed for MES or ERP integration?','Define the exchanged data, record ownership, supported protocols, network boundaries, error handling and acceptance checks with both system providers.')]
auto=header('CONTROL & AUTOMATION','One coordinated line.<br>A clearer view of production.','Connect process recipes, equipment coordination and factory information through a central control system.','control')
auto+=section('<div class="grid-3"><div class="guide-card"><small>01 / CONTROL</small><h3>Coordinate the equipment.</h3><p>Link handling and process equipment through the line’s central control architecture.</p></div><div class="guide-card"><small>02 / OPERATE</small><h3>Match the production mode.</h3><p>Use fixed or flexible process scheduling according to the agreed production scenario.</p></div><div class="guide-card"><small>03 / CONNECT</small><h3>Make data useful.</h3><p>Define reporting and factory system interfaces so the right information reaches the right team.</p></div></div>'+source('https://en.daimengtech.com/products/中央智能控制系统'))
auto+=section('<div class="split"><div><span class="eyebrow">INTEGRATION STARTS WITH A PLAN</span><h2>Specify the interface.<br>Not just the connection.</h2><p>Bring your IT team and production team into the conversation early. A shared data map makes responsibilities and acceptance criteria clear.</p>'+link('Read the MES integration guide','/insights/mes-integration/')+'</div>'+table([('Production inputs','Agree work order, profile and recipe fields'),('Production outputs','Define batch status, completion and reporting data'),('Exceptions','Specify unavailable connections and manual recovery'),('Acceptance','Test with representative production scenarios')])+'</div>','muted')+section('<h2>Control system questions</h2>'+faq(auto_faq))+cta()
page('/automation/','Anodizing Line Automation & MES Integration | Daimeng','Explore Daimeng central control systems for anodizing lines, fixed and flexible production modes, reporting and MES / ERP integration planning.',auto,auto_faq)

equipment=header('SUPPORTING EQUIPMENT','The details that keep<br>production moving.','Define the supporting systems alongside your anodizing line, with clear process and equipment interfaces.')+section('<div class="grid-2"><article class="guide-card"><small>HANDLING</small><h3>Loading & unloading</h3><p>Discuss automated handling equipment against your profile sizes, loading pattern and upstream workflow.</p>'+btn('Discuss handling','/contact/?solution=equipment','outline')+'</article><article class="guide-card"><small>PROCESS SUPPORT</small><h3>Acid recovery</h3><p>Include acid recovery requirements in the process brief and confirm compatibility with the line’s operating conditions.</p>'+btn('Discuss process equipment','/contact/?solution=equipment','outline')+'</article><article class="guide-card"><small>FINISHING</small><h3>Electrophoretic coating</h3><p>Review the coating stage, rinsing, curing and transfer requirements as part of the specified finishing route.</p>'+btn('Discuss ED coating','/contact/?solution=equipment','outline')+'</article><article class="guide-card"><small>INTEGRATION</small><h3>Utilities & interfaces</h3><p>Document power, cooling, water, extraction and wastewater treatment responsibilities before finalizing supply scope.</p>'+btn('Prepare your equipment brief','/contact/?solution=equipment','outline')+'</article></div>')+cta()
page('/anodizing-equipment/','Aluminium Anodizing Equipment & Line Integration | Daimeng','Plan loading equipment, acid recovery, electrophoretic coating and line interfaces with Daimeng aluminium surface treatment solutions.',equipment)

