projects=header('PROJECT REFERENCES','Real projects.<br>A useful starting point.','Explore published Daimeng references and discuss how your own production requirements compare.')+section('<div class="pill-row" aria-label="Filter projects"><button class="pill" data-filter="all" aria-pressed="true">All references</button><button class="pill" data-filter="malaysia" aria-pressed="false">Malaysia</button><button class="pill" data-filter="china" aria-pressed="false">China</button></div><div class="grid-2"><article class="product-card" data-region="malaysia"><div class="card-body"><span class="kicker">MALAYSIA / VERTICAL ANODIZING</span><h3>Press Metal PV<br>(SARAWAK) SDN. BHD</h3><p>Listed by Daimeng as a 4,000-ton fully automatic vertical anodizing production line.</p>'+link('View reference','/projects/press-metal/')+'</div></article><article class="product-card" data-region="china"><div class="card-body"><span class="kicker">CHINA / VERTICAL ANODIZING</span><h3>Jiangsu Sulu<br>Precision Technology</h3><p>Listed by Daimeng as a 15,000-ton fully automatic vertical anodizing production line.</p>'+link('View published reference',sulu_url)+'</div></article></div><p class="note">Capacity labels follow the published references. Their measurement period is not stated on those reference pages.</p>')+cta()
projects=projects.replace('href="'+sulu_url+'"','href="/projects/jiangsu-sulu/"').replace('View published reference','View reference')
page('/projects/','Aluminium Anodizing Line Project References | Daimeng','Explore Daimeng published vertical anodizing project references in Malaysia and China, and discuss the requirements of your own production line.',projects)
page('/projects/jiangsu-sulu/','Jiangsu Sulu Vertical Anodizing Reference | Daimeng','Explore Daimeng’s published Jiangsu Sulu Precision Technology reference for a fully automatic vertical anodizing production line.',header('CHINA / PROJECT REFERENCE','Jiangsu Sulu<br>Precision Technology','A vertical anodizing production line listed in Daimeng’s published customer references.')+section('<div class="article">'+table([('Customer','Jiangsu Sulu Precision Technology Co., Ltd.'),('Chinese company name','江苏苏铝精密科技有限公司'),('Market','China'),('Line configuration','Fully automatic vertical anodizing'),('Published capacity label','15,000-ton (period not specified)'),('Reference published','29 July 2023')])+source(sulu_url,'View Daimeng’s original project reference')+'<h2>Define your own production scenario</h2><p>When comparing a published project with your needs, confirm the profile envelope, finish mix, operating schedule and capacity basis. Each factory requires its own process and layout review.</p>'+btn('Discuss a vertical line project','/contact/?solution=vertical','dark')+'</div>'))
press=header('MALAYSIA / PROJECT REFERENCE','Press Metal PV<br>(SARAWAK) SDN. BHD','A fully automatic vertical anodizing production line in Daimeng’s published customer references.')+section('<div class="split"><div>'+image('vertical','Daimeng vertical anodizing equipment, shown as an equipment reference')+'<p class="note">Daimeng equipment image for illustration; not a verified photograph of this project site.</p></div><div><span class="eyebrow">PUBLISHED PROJECT OVERVIEW</span>'+table([('Customer','Press Metal PV (SARAWAK) SDN. BHD'),('Market','Malaysia'),('Line type','Fully automatic vertical anodizing'),('Published capacity label','4,000-ton (period not specified)'),('Reference published','3 March 2026')])+source(press_url,'View Daimeng’s original project reference')+'</div></div>')+section('<div class="article"><h2>Planning a similar project?</h2><p>A customer reference can help establish the type of line under discussion. Your own design still starts with profile sizes, finish specifications, annual demand and the conditions in your factory.</p><p>Include your expected product mix and operating schedule in the brief so capacity discussions use a shared set of assumptions.</p>'+btn('Discuss your vertical line project','/contact/?solution=vertical','dark')+'</div>','muted')
page('/projects/press-metal/','Press Metal Malaysia Vertical Anodizing Reference | Daimeng','Read Daimeng’s published Press Metal PV (SARAWAK) project reference for a fully automatic vertical anodizing line in Malaysia.',press)

about_profile=(ROOT/'src/about-profile.html').read_text(encoding='utf-8')
page('/about/','About Daimeng | Aluminium Surface Treatment Engineering','Discover Daimeng Technology: aluminium anodizing lines, automated handling, intelligent control and project planning for manufacturers.',header('ABOUT DAIMENG','Engineering aluminium<br>surface treatment.','Discover the equipment, engineering approach and connected control systems behind Daimeng Technology. From your first production brief to a clearly defined line configuration.')+section(about_profile)+cta())

page('/insights/','Anodizing Line Planning & Engineering Guides | Daimeng','Practical guides to selecting an anodizing line, preparing a project brief and planning MES integration for an aluminium finishing plant.',header('ENGINEERING INSIGHTS','Better questions.<br>Better project decisions.','Practical planning guides for aluminium manufacturers preparing their next anodizing investment.')+section(guides())+cta())

article1='''<p class="large-copy">Choose the configuration after you understand the product mix, process route and factory constraints. A useful comparison begins with the same production assumptions for both options.</p><h2>1. Describe the workpiece envelope</h2><p>List the shortest and longest profiles, representative cross-sections, weights and the share of production each family represents. Include occasional products that the new line must accommodate. A nominal maximum size alone does not describe a factory’s production mix.</p><h2>2. Review the building before the layout</h2><p>Record usable floor space, clear internal height, columns, access openings and equipment maintenance areas. Vertical and horizontal handling arrangements create different layout questions. Ask for drawings that show loading, transfer and service space rather than just the process tanks.</p><h2>3. Compare on the same capacity basis</h2><p>Define output using agreed operating hours, loading assumptions and finish mix. Tonnes alone may hide differences in surface area and processing time. Ask how each proposal accounts for product changes, planned downtime and the slowest stage of the route.</p><h2>4. Specify the finish mix</h2><p>Identify required appearances, film thicknesses and acceptance criteria. Include any planned coloring or downstream coating. A line optimized around a single route should be compared differently from one expected to handle frequent changes.</p><h2>5. Make the decision traceable</h2><p>Build a comparison matrix with your team. Include building modifications, equipment scope, utility interfaces, operator tasks and the data required from the control system. Record every assumption that could change the result.</p><div class="notice">The line selector provides a discussion starting point. Final selection needs a project-specific engineering review.</div>'''
article2='''<p class="large-copy">A clear brief helps suppliers compare the same project. Prepare a small set of practical documents before asking for a quotation.</p><h2>Products and quality</h2><p>Share drawings or a product family list covering dimensions, alloy, weight and surface area when available. State the finish requirements, inspection approach and the customer specifications you need to satisfy.</p><h2>Demand and production mix</h2><p>Record current demand, the expected ramp-up and your planning horizon. Split demand by product family and finish. Include operating shifts and working days so output targets can be interpreted consistently.</p><h2>Factory and utilities</h2><p>Provide a dimensioned building layout with columns, access points and clear height. Identify available electrical supply, water, cooling, compressed air, extraction and wastewater treatment interfaces. Mark which infrastructure already exists and which must be included in the project.</p><h2>Automation and information</h2><p>Describe operator tasks, batch identification, reporting and any connection to existing factory software. Involve both production and IT teams. List the information to exchange before choosing a communication method.</p><h2>Delivery and responsibility</h2><p>Separate the scope into equipment supply, civil work, installation, commissioning, training and ongoing service. Record the responsible party for each item. Agree how acceptance will be measured using representative products and operating conditions.</p><h2>A concise enquiry checklist</h2><ul><li>Country, location and project stage</li><li>Product dimensions, alloy and finish requirements</li><li>Monthly output target and planned operating schedule</li><li>Factory drawings and available utilities</li><li>Control, reporting and traceability requirements</li><li>Desired timing and supply responsibilities</li></ul><p>Use the enquiry form to prepare the first version of your brief. You can download a copy before submitting it.</p>'''
article3='''<p class="large-copy">A network connection is only one part of integration. The important work is agreeing what each system knows, what it controls and what happens when information is missing.</p><h2>Start with the production workflow</h2><p>Map how an order becomes a production batch, how the batch is identified and how completion is reported. Identify the people who resolve exceptions. Use this workflow to decide which information needs to move between the line and factory management software.</p><h2>Define a shared data dictionary</h2><p>Document identifiers, units, timestamps and allowed values. A profile code or recipe name is useful only if both sides interpret it consistently. Decide which system owns each record and how changes are approved.</p><h2>Agree the integration boundary</h2><p>Daimeng’s published control system information describes interfaces for factory management systems, including MES and ERP. Discuss the exact data, connection method and responsibilities with the engineering and IT teams before finalizing a project.</p><h2>Plan for interrupted connections</h2><p>Specify how operators see a missing connection, what production can continue and how records are reconciled afterwards. Discuss duplicate records, incomplete messages and changes received during production.</p><h2>Test the real scenarios</h2><p>Include a normal batch, a revised order, an unavailable connection and a restart in acceptance planning. Define success in operational terms: the right information arrives once, the operator understands the state, and the systems agree on the result.</p><p>Integration scope and network design should be approved by the people responsible for both systems.</p>'''
for slug,title,desc,body in [('vertical-vs-horizontal','Vertical vs Horizontal Anodizing Lines','A practical decision guide for comparing anodizing line configurations using profiles, capacity, building constraints and process requirements.',article1),('anodizing-line-planning','How to Prepare an Anodizing Line Project Brief','Prepare the product, capacity, factory and automation information needed for a useful aluminium anodizing line quotation.',article2),('mes-integration','Planning MES / ERP Integration for an Anodizing Line','Define data ownership, interfaces and acceptance checks before connecting an anodizing line to factory management software.',article3)]:
    page('/insights/'+slug+'/',title+' | Daimeng',desc,header('ENGINEERING GUIDE',title,desc)+section('<article class="article"><div class="article-meta">PROJECT PLANNING / DAIMENG TECHNOLOGY</div>'+body+btn('Build your project brief','/contact/','dark')+'</article>')+cta())

selector=header('LINE SELECTOR','Find a useful<br>starting point.','Tell us about your workpieces and available space. Get a preliminary direction to discuss with an engineer.')+section('''<div class="split"><div><span class="eyebrow">A THREE-QUESTION START</span><h2>Your production<br>sets the direction.</h2><p>This tool organizes an initial conversation. It does not calculate capacity or replace a factory layout review.</p><p>You can carry the result into your project enquiry.</p></div><form id="selector" class="choice-panel"><div class="form-grid"><label class="field full">Primary product mix<select name="mix"><option value="long">Mainly long aluminium profiles</option><option value="mixed">Mixed lengths and profile families</option><option value="parts">Small parts or non-profile components</option></select></label><label class="field full">Building height flexibility<select name="height"><option value="flexible">New building or flexible clear height</option><option value="limited">Existing building with height constraints</option><option value="unknown">Not yet confirmed</option></select></label><label class="field full">Production priority<select name="priority"><option value="volume">High-volume repeat production</option><option value="variety">Frequent product or finish changes</option><option value="review">Still defining the process</option></select></label><button type="submit" class="btn dark full">Show my starting point</button></div><div id="selector-result" class="choice-result" hidden aria-live="polite"></div></form></div>''')
page('/line-selector/','Vertical or Horizontal? Anodizing Line Selector | Daimeng','Use a simple product and factory questionnaire to prepare your discussion about a vertical or horizontal anodizing line.',selector)

contact=header('PROJECT ENQUIRY','Let’s define<br>your next production line.','Share what you know. We’ll use your brief as the starting point for a technical conversation.')+section('''<div class="contact-layout"><div><span class="eyebrow">TALK TO DAIMENG</span><h2>A clear brief.<br>A useful conversation.</h2><p style="margin-top:25px">Tell us about your products, factory and intended output. You can save a copy of your brief at any time.</p><div class="contact-details"><div><small>YOUR CONTACT</small><strong>Pearl Lee · Sales</strong></div><div><small>EMAIL</small><a href="mailto:DM_tech@yeah.net">DM_tech@yeah.net</a></div><div><small>PHONE / WHATSAPP</small><a href="tel:+8618676108902">+86 186 7610 8902</a><br><a class="text-link" href="https://wa.me/8618676108902" target="_blank" rel="noopener">Open WhatsApp</a></div><div><small>VISIT BY APPOINTMENT</small>No. 12 Kebao North Road, Shishan Town,<br>Nanhai District, Foshan, Guangdong, China</div></div></div><div class="form-panel"><form id="enquiry-form"><div class="form-grid"><label class="field">Full name *<input name="name" autocomplete="name" maxlength="100" required></label><label class="field">Work email *<input type="email" name="email" autocomplete="email" maxlength="180" required></label><label class="field">Company *<input name="company" autocomplete="organization" maxlength="160" required></label><label class="field">Country / region *<input name="country" autocomplete="country-name" maxlength="100" required></label><label class="field">Solution of interest *<select name="solution" required><option value="">Please select</option><option value="vertical">Vertical anodizing line</option><option value="horizontal">Horizontal anodizing line</option><option value="automation">Control / MES integration</option><option value="equipment">Supporting equipment</option><option value="review">Help me choose</option></select></label><label class="field">Target output (tonnes / month)<input type="number" name="capacity" min="1" max="100000" inputmode="numeric" placeholder="e.g. 2000"></label><label class="field">Project timing<select name="timeline"><option value="exploring">Early research</option><option value="12months">Within 12 months</option><option value="6months">Within 6 months</option><option value="3months">Within 3 months</option></select></label><label class="field">Phone / WhatsApp<input type="tel" name="phone" autocomplete="tel" maxlength="50"></label><label class="field full">Tell us about your project *<textarea name="message" minlength="20" maxlength="4000" placeholder="Profile sizes, required finishes, factory conditions and what you want to achieve..." required></textarea></label><label class="honeypot" aria-hidden="true">Leave this empty<input name="website" tabindex="-1" autocomplete="off"></label><label class="checkbox full"><input type="checkbox" name="consent" required><span>I agree to the use of my details to respond to this project enquiry. See the <a href="/privacy/">privacy notice</a>. *</span></label></div><button class="btn dark" type="submit">Submit project enquiry</button><button class="btn outline" type="button" id="download-brief">Prepare my brief</button><p class="note">Required fields are marked *. This form is for project enquiries, not newsletter subscriptions.</p><div class="form-status" id="form-status" role="status" aria-live="polite"></div><div id="enquiry-success" hidden><a class="text-link" id="email-brief" href="mailto:DM_tech@yeah.net">Open an email with my brief</a><p class="note">Opening an email creates a draft in your email app. You choose when to send it.</p></div></form><noscript><p>JavaScript is required for the enquiry form. Please email <a href="mailto:DM_tech@yeah.net">DM_tech@yeah.net</a> instead.</p></noscript></div></div>''')
page('/contact/','Request an Anodizing Line Proposal | Contact Daimeng','Tell Daimeng about your aluminium profiles, capacity, finishes and factory requirements. Request a tailored anodizing line discussion.',contact)

privacy=header('PRIVACY','Your project information.','How information submitted through this website is handled.')+section('''<div class="article"><h2>Information you provide</h2><p>The enquiry form asks for your name, business contact information and project requirements. Optional fields help provide context. Do not include passwords, payment information or other sensitive records.</p><h2>How it is used</h2><p>Details are used to organize your enquiry, identify the relevant solution and prepare project follow-up. When present, campaign source fields are attached to the enquiry to identify where it originated. Submitting an enquiry does not subscribe you to promotional email.</p><h2>Storage and contact</h2><p>Enquiries submitted to this installation are stored on the website operator’s server. Access should be restricted to the people responsible for project enquiries. To request access, correction or deletion, contact <a href="mailto:DM_tech@yeah.net">DM_tech@yeah.net</a> and identify your enquiry reference.</p><h2>Browser preferences and external services</h2><p>This website uses session storage for campaign attribution during your visit. It does not include advertising trackers or third-party analytics scripts. WhatsApp and email links open separate services with their own privacy practices. An email link creates a draft; it does not send a message automatically.</p><h2>Local preview</h2><p>When accessed through a localhost address, this is a local preview. Submitted enquiries are saved on that computer and are not automatically delivered to the company’s email inbox.</p></div>''')
page('/privacy/','Privacy Notice | Daimeng Technology','How project enquiries and contact information are handled on the Daimeng website.',privacy)
page('/404/','Page Not Found | Daimeng Technology','The requested page could not be found.',header('PAGE NOT FOUND','Let’s get you<br>back on track.','The page you requested is not available.')+section('<div class="actions">'+btn('Back to home','/','dark')+btn('Explore solutions','/solutions/','outline')+'</div>'),noindex=True)
